import 'package:flutter/material.dart';

import '../../core/constants/app_constants.dart';

/// The Veylora mark: a "V" of two layers (amber and cream) that cross at the
/// vertex. Generated by `tool/brand/generate_brand_assets.py`.
class BrandMark extends StatelessWidget {
  const BrandMark({super.key, this.size = 40});

  static const String asset = 'assets/branding/veylora_mark.png';

  final double size;

  @override
  Widget build(BuildContext context) {
    return Image.asset(
      asset,
      width: size,
      height: size,
      filterQuality: FilterQuality.medium,
      semanticLabel: '${AppConstants.appName} logo',
    );
  }
}
